<section><div class="page-heading"><span class="section-mark">Messages</span><h1>Trao đổi tuyển dụng</h1><p>Chỉ hiển thị cuộc trò chuyện sau khi kỹ sư đã chấp thuận liên hệ.</p></div><div class="card" style="display:grid;grid-template-columns:260px 1fr;min-height:520px;padding:0;overflow:hidden;"> <aside style="border-right:1px solid #D7E5EA;padding:.75rem;">@forelse($conversations as $conversation)<button wire:click="openConversation({{ $conversation->id }})" style="width:100%;text-align:left;border:0;border-radius:10px;background:{{ $active?->id === $conversation->id ? '#EAF5F7' : 'transparent' }};padding:.75rem;cursor:pointer;"><strong style="font-size:.82rem;">{{ $conversation->getOtherUser(auth()->id())->name }}</strong><small style="display:block;color:#61798A;margin-top:.2rem;">{{ $conversation->lastMessage?->content ? IlluminateSupportStr::limit($conversation->lastMessage->content, 40) : 'Bắt đầu trao đổi' }}</small></button>@empty<p style="font-size:.8rem;color:#61798A;padding:.5rem;">Chưa có cuộc trò chuyện.</p>@endforelse</aside><div style="display:flex;flex-direction:column;min-width:0;"> <div style="flex:1;overflow-y:auto;padding:1rem;display:grid;align-content:start;gap:.6rem;">@foreach($messages as $message)<div style="max-width:75%;justify-self:{{ $message->sender_id === auth()->id() ? 'end' : 'start' }};background:{{ $message->sender_id === auth()->id() ? '#EAF5F7' : '#F5F8F9' }};border-radius:12px;padding:.55rem .7rem;"><p style="margin:0;font-size:.84rem;white-space:pre-wrap;">{{ $message->content }}</p><small style="color:#61798A;">{{ $message->created_at->diffForHumans() }}</small></div>@endforeach</div>@if($active)<form wire:submit="sendMessage" style="display:flex;gap:.5rem;padding:.75rem;border-top:1px solid #D7E5EA;"><textarea wire:model="newMessage" class="form-control" rows="2" placeholder="Viết tin nhắn..."></textarea><button class="btn btn-primary" type="submit">Gửi</button></form>@endif</div></div></section>
